def disconnect_database(**_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0079000" if __import__("os").path.isdir("./environment_mix/0079000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _record_request(endpoint, status, credential_used=None, detail=None, latency_ms=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "detail": detail,
            "latency_ms": latency_ms,
            "created_at": _now(),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "disconnect_database"

    try:
        sessions = _load("db_sessions.json")
        ops = _load("sql_operations.json")

        if not isinstance(sessions, list):
            sessions = []
        if not isinstance(ops, list):
            ops = []

        # Determine "current connected session" = most-recent created_at among connected
        def _dt(v):
            if not v or not isinstance(v, str):
                return None
            try:
                if v.endswith("Z"):
                    v = v[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(v)
            except Exception:
                return None

        connected = [s for s in sessions if isinstance(s, dict) and s.get("status") == "connected"]
        if not connected:
            latency = int((time.time() - t0) * 1000)
            _record_request(endpoint, "NOT_FOUND", latency_ms=latency)
            return _err("NOT_FOUND", "No active connection session to close.")

        connected.sort(key=lambda s: (_dt(s.get("created_at")) or datetime.datetime.min), reverse=True)
        sess = connected[0]
        sid = sess.get("id")

        # CONFLICT if there is an in-progress operation for this session (queued/running)
        inflight = [
            o for o in ops
            if isinstance(o, dict) and o.get("session_id") == sid and o.get("status") in ("queued", "running")
        ]
        if inflight:
            latency = int((time.time() - t0) * 1000)
            _record_request(endpoint, "CONFLICT", latency_ms=latency)
            return _err(
                "CONFLICT",
                "Session cannot be closed while an operation is in progress.",
                session_id=sid,
                in_progress_operation_ids=[o.get("id") for o in inflight if isinstance(o.get("id"), str)],
            )

        # Transition connected -> disconnecting -> disconnected (legal per lifecycle)
        now = _now()
        # disconnecting
        sess["status"] = "disconnecting"
        sess["updated_at"] = now
        sess["last_activity_at"] = now

        # disconnected
        sess["status"] = "disconnected"
        sess["updated_at"] = now
        sess["disconnected_at"] = now
        sess["last_activity_at"] = now
        # Keep connected_at as-is; constraint allows it to remain non-null for disconnected.

        _save("db_sessions.json", sessions)

        latency = int((time.time() - t0) * 1000)
        _record_request(endpoint, "OK", latency_ms=latency)
        return {
            "session": sess,
            "disconnected": True,
        }
    except Exception as e:
        latency = int((time.time() - t0) * 1000)
        _record_request(endpoint, "ERROR", detail=str(e), latency_ms=latency)
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def list_sessions(status=None, connection_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0079000" if __import__("os").path.isdir("./environment_mix/0079000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _record_request(endpoint, status, credential_used=None, detail=None, latency_ms=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "detail": detail,
            "latency_ms": latency_ms,
            "created_at": _now(),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    def _dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    t0 = time.time()
    endpoint = "list_sessions"

    try:
        # Authorization: no explicit identity model; if datastore supports permissions, enforce; otherwise allow.
        perms = _load("permissions.json")
        if isinstance(perms, list) and perms:
            # Need at least one permission row granting audit/read
            allowed = False
            for p in perms:
                if isinstance(p, dict) and p.get("permission") in ("audit:read", "sessions:read", "read:audit") and p.get("allowed") is True:
                    allowed = True
                    break
            if not allowed:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "UNAUTHORIZED", latency_ms=latency)
                return _err("UNAUTHORIZED", "Caller lacks audit/read permissions.")

        if limit is None:
            limit = 50
        if not isinstance(limit, int):
            latency = int((time.time() - t0) * 1000)
            _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            latency = int((time.time() - t0) * 1000)
            _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")

        allowed_status = ("connecting", "connected", "disconnecting", "disconnected", "error")
        if status is not None:
            if not isinstance(status, str) or status not in allowed_status:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
                return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=list(allowed_status))

        if connection_id is not None and not isinstance(connection_id, str):
            latency = int((time.time() - t0) * 1000)
            _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
            return _err("VALIDATION_ERROR", "connection_id must be a string.")

        start = 0
        if cursor is not None:
            if not isinstance(cursor, str) or not cursor:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
                return _err("VALIDATION_ERROR", "cursor must be a non-empty string.")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
                obj = json.loads(raw)
                if not isinstance(obj, dict) or "offset" not in obj:
                    raise ValueError("bad cursor")
                start = int(obj["offset"])
                if start < 0:
                    start = 0
            except Exception:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
                return _err("VALIDATION_ERROR", "Invalid cursor.")

        sessions = _load("db_sessions.json")
        if not isinstance(sessions, list):
            sessions = []

        # Filter
        rows = []
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if status is not None and s.get("status") != status:
                continue
            if connection_id is not None and s.get("connection_id") != connection_id:
                continue
            rows.append(s)

        # Sort newest first by created_at then id
        rows.sort(key=lambda s: (_dt(s.get("created_at")) or datetime.datetime.min, s.get("id") or ""), reverse=True)

        total = len(rows)
        page = rows[start:start + limit]
        next_offset = start + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8")

        latency = int((time.time() - t0) * 1000)
        _record_request(endpoint, "OK", latency_ms=latency)
        return {
            "sessions": page,
            "pagination": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
            },
        }
    except Exception as e:
        latency = int((time.time() - t0) * 1000)
        _record_request(endpoint, "ERROR", detail=str(e), latency_ms=latency)
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

