        perms = _load("permissions.json")
        if isinstance(perms, list) and perms:
            allowed = False
            for p in perms:
                if isinstance(p, dict) and p.get("permission") in ("audit:read", "operations:read", "read:audit") and p.get("allowed") is True:
                    allowed = True
                    break
            if not allowed:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "UNAUTHORIZED", latency_ms=latency)
                return _err("UNAUTHORIZED", "Caller lacks audit/read permissions.")

        if session_id is not None and (not isinstance(session_id, str) or not session_id):
            latency = int((time.time() - t0) * 1000)
            _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
            return _err("VALIDATION_ERROR", "session_id must be a non-empty string.")

        allowed_status = ("queued", "running", "succeeded", "failed", "cancelled")
        if status is not None:
            if not isinstance(status, str) or status not in allowed_status:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
                return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=list(allowed_status))

        allowed_tool = ("execute_query", "show_tables", "describe_table")
        if tool_name is not None:
            if not isinstance(tool_name, str) or tool_name not in allowed_tool:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
                return _err("VALIDATION_ERROR", "Invalid tool_name filter.", allowed=list(allowed_tool))

        # Tool schema lists simplified kinds, map to stored operation_kind values
        allowed_kind_req = ("read", "write", "introspection", "other")
        if operation_kind is not None:
            if not isinstance(operation_kind, str) or operation_kind not in allowed_kind_req:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
                return _err("VALIDATION_ERROR", "Invalid operation_kind filter.", allowed=list(allowed_kind_req))

        if limit is None:
            limit = 50
        if not isinstance(limit, int):
            latency = int((time.time() - t0) * 1000)
            _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            latency = int((time.time() - t0) * 1000)
            _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")

        start = 0
        if cursor is not None:
            if not isinstance(cursor, str) or not cursor:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
                return _err("VALIDATION_ERROR", "cursor must be a non-empty string.")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
                obj = json.loads(raw)
                if not isinstance(obj, dict) or "offset" not in obj:
                    raise ValueError("bad cursor")
                start = int(obj["offset"])
                if start < 0:
                    start = 0
            except Exception:
                latency = int((time.time() - t0) * 1000)
                _record_request(endpoint, "VALIDATION_ERROR", latency_ms=latency)
                return _err("VALIDATION_ERROR", "Invalid cursor.")

        ops = _load("sql_operations.json")
        if not isinstance(ops, list):
            ops = []

        # Map request operation_kind into stored enums:
        # read -> select; write -> insert/update/delete/ddl/transaction; introspection -> introspection; other -> other
        def _match_kind(op_kind_stored):
            if operation_kind is None:
                return True
            if op_kind_stored not in ("select", "insert", "update", "delete", "ddl", "transaction", "other", "introspection"):
                return False
            if operation_kind == "read":
                return op_kind_stored == "select"
            if operation_kind == "write":
                return op_kind_stored in ("insert", "update", "delete", "ddl", "transaction")
            if operation_kind == "introspection":
                return op_kind_stored == "introspection"
            if operation_kind == "other":
                return op_kind_stored == "other"
            return False

        rows = []
        for o in ops:
            if not isinstance(o, dict):
                continue
            if session_id is not None and o.get("session_id") != session_id:
                continue
            if status is not None and o.get("status") != status:
                continue
            if tool_name is not None and o.get("tool_name") != tool_name:
                continue
            if not _match_kind(o.get("operation_kind")):
                continue
            # Return high-level metadata without large result payloads: do not join operation_results
            rows.append(o)

        rows.sort(key=lambda o: (_dt(o.get("created_at")) or datetime.datetime.min, o.get("id") or ""), reverse=True)

        total = len(rows)
        page = rows[start:start + limit]
        next_offset = start + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8")

        latency = int((time.time() - t0) * 1000)
        _record_request(endpoint, "OK", latency_ms=latency)
        return {
            "operations": page,
            "pagination": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
            },
        }
    except Exception as e:
