        _record_request(endpoint, "ERROR", detail=str(e), latency_ms=latency)
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def get_operation(operation_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0079000" if __import__("os").path.isdir("./environment_mix/0079000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, latency_ms, **details):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        row.update(details)
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # Validate
    if not isinstance(operation_id, str) or not operation_id.strip():
        _log("get_operation", "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "operation_id must be a non-empty string", field="operation_id")

    ops = _load("sql_operations.json")
    op = None
    for r in ops:
        if isinstance(r, dict) and r.get("id") == operation_id:
            op = r
            break

    if op is None:
        _log("get_operation", "NOT_FOUND", (time.time() - t0) * 1000, operation_id=operation_id)
        return _err("NOT_FOUND", "Operation not found", operation_id=operation_id)

    # "Visible to caller" — no explicit identity model in this datastore.
    # Ambient auth: treat store as scoped to the caller; therefore existence implies visibility.

    _log("get_operation", "OK", (time.time() - t0) * 1000, operation_id=operation_id)
    return {"operation": op}

