            break

    if res is None:
        _log("get_operation_result", "NOT_FOUND", (time.time() - t0) * 1000, operation_id=operation_id)
        return _err("NOT_FOUND", "Operation result not found", operation_id=operation_id)

    # Return only the externally relevant fields
    out = {
        "operation_id": operation_id,
        "result_format": res.get("result_format"),
        "truncated": res.get("truncated"),
        "byte_size": res.get("byte_size"),
        "payload": res.get("payload"),
    }

    _log("get_operation_result", "OK", (time.time() - t0) * 1000, operation_id=operation_id)
    return {"result": out}
